#[test]
fn bindgen_test_layout_qihse_result_set_s() {
    const UNINIT: ::std::mem::MaybeUninit<qihse_result_set_s> = ::std::mem::MaybeUninit::uninit();
    let ptr = UNINIT.as_ptr();
    assert_eq!(
        ::std::mem::size_of::<qihse_result_set_s>(),
        16usize,
        concat!("Size of: ", stringify!(qihse_result_set_s))
    );
    assert_eq!(
        ::std::mem::align_of::<qihse_result_set_s>(),
        8usize,
        concat!("Alignment of ", stringify!(qihse_result_set_s))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).results) as usize - ptr as usize },
        0usize,
        concat!(
            "Offset of field: ",
            stringify!(qihse_result_set_s),
            "::",
            stringify!(results)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).count) as usize - ptr as usize },
        8usize,
        concat!(
            "Offset of field: ",
            stringify!(qihse_result_set_s),
            "::",
            stringify!(count)
        )
    );
}
