#[test]
fn bindgen_test_layout_qihse_hybrid_request_s() {
    const UNINIT: ::std::mem::MaybeUninit<qihse_hybrid_request_s> =
        ::std::mem::MaybeUninit::uninit();
    let ptr = UNINIT.as_ptr();
    assert_eq!(
        ::std::mem::size_of::<qihse_hybrid_request_s>(),
        168usize,
        concat!("Size of: ", stringify!(qihse_hybrid_request_s))
    );
    assert_eq!(
        ::std::mem::align_of::<qihse_hybrid_request_s>(),
        8usize,
        concat!("Alignment of ", stringify!(qihse_hybrid_request_s))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).query_a) as usize - ptr as usize },
        0usize,
        concat!(
            "Offset of field: ",
            stringify!(qihse_hybrid_request_s),
            "::",
            stringify!(query_a)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).query_b) as usize - ptr as usize },
        80usize,
        concat!(
            "Offset of field: ",
            stringify!(qihse_hybrid_request_s),
            "::",
            stringify!(query_b)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).fusion_constant_k) as usize - ptr as usize },
        160usize,
        concat!(
            "Offset of field: ",
            stringify!(qihse_hybrid_request_s),
            "::",
            stringify!(fusion_constant_k)
        )
    );
}
